import mongoose,{Schema} from 'mongoose';
const option=new Schema({label:String,priceAdjustment:{type:Number,default:0},isDefault:Boolean},{_id:true});
export const Category=mongoose.model('Category',new Schema({name:{type:String,required:true,index:true},icon:String,displayOrder:{type:Number,default:0},active:{type:Boolean,default:true}},{timestamps:true}));
export const MenuItem=mongoose.model('MenuItem',new Schema({name:{type:String,required:true,index:true},description:String,sku:{type:String,index:true,sparse:true},barcode:String,image:String,price:{type:Number,required:true,min:0},cost:{type:Number,default:0,min:0},category:{type:Schema.Types.ObjectId,ref:'Category',required:true},taxCategory:{type:String,default:'standard'},kitchenStation:{type:String,default:'main'},preparationTime:{type:Number,default:10},available:{type:Boolean,default:true},tags:[String],modifierGroups:[{name:String,required:Boolean,multiple:Boolean,options:[option]}],variants:[option],addons:[option]},{timestamps:true}));
